import { watchDom } from '../../core/observer';
import { wasApplied, markApplied } from '../utils/dom';
import { createIcon, iconNameFromText } from '../utils/icons';

function enhanceSettingsIcons() {
    const rows = document.querySelectorAll(
        '.settingsPage a, .settingsPage button, .userSettingsPage a, .userSettingsPage button, .dashboardDocument a, .dashboardDocument button'
    );

    rows.forEach((row) => {
        if (wasApplied(row, 'ptvSettingsIcon')) return;

        const label = row.getAttribute('title')
            || row.getAttribute('aria-label')
            || row.textContent
            || '';

        const iconName = iconNameFromText(label);
        if (!iconName) return;

        markApplied(row, 'ptvSettingsIcon');
        row.classList.add('ptv-settings-row');

        const oldIcon = row.querySelector(
            '.material-icons, .material-icons-round, .material-icons-outlined, i'
        );

        if (oldIcon) {
            oldIcon.classList.add('ptv-hidden-stock-icon');
        }

        if (!row.querySelector('.ptv-settings-icon')) {
            row.prepend(createIcon(iconName, 'ptv-icon ptv-settings-icon'));
        }
    });
}

watchDom(enhanceSettingsIcons);
enhanceSettingsIcons();
